// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/preservation/IStreamPreservationRecords.sol";
import {
    StreamArtistRecordPublicationTypes as P
} from "../../interfaces/stream/artist/StreamArtistRecordPublicationTypes.sol";

/// @notice The existing fourteen-word generic record preimage, shared by direct and detached writes.
library StreamCollectionRecordHashes {
    bytes32 internal constant RECORD_DOMAIN = keccak256("6529stream.preservation-record.v2");
    bytes32 internal constant CHAIN_DOMAIN =
        0x0e7a0feb85d4a4a3e90074703c19de35786e11afaae8f9868aa2a911bcfa1609;

    struct Preimage {
        bytes32 domain;
        uint256 chainId;
        address host;
        address core;
        address recorder;
        uint256 collectionId;
        bytes32 recordType;
        bytes32 subjectId;
        bytes32 contentHash;
        bytes32 uriHash;
        bytes32 schemaId;
        bytes32 signatureScheme;
        bytes32 signatureHash;
        uint64 effectiveAt;
    }

    function hashRef(uint16 algorithm, bytes memory digest, bytes32 canonicalizationId)
        internal
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(algorithm, keccak256(digest), canonicalizationId));
    }

    function recordHash(
        address core,
        address recorder,
        uint256 collectionId,
        IStreamPreservationRecords.CollectionRecord memory record
    ) internal view returns (bytes32) {
        Preimage memory p;
        p.domain = RECORD_DOMAIN;
        p.chainId = block.chainid;
        p.host = address(this);
        p.core = core;
        p.recorder = recorder;
        p.collectionId = collectionId;
        p.recordType = record.recordType;
        p.subjectId = record.subjectId;
        p.contentHash = hashRef(
            record.contentHash.algorithm,
            record.contentHash.digest,
            record.contentHash.canonicalizationId
        );
        p.uriHash = keccak256(bytes(record.uri));
        p.schemaId = record.schemaId;
        p.signatureScheme = record.signatureScheme;
        p.signatureHash = hashRef(
            record.signatureHash.algorithm,
            record.signatureHash.digest,
            record.signatureHash.canonicalizationId
        );
        p.effectiveAt = record.effectiveAt;
        return keccak256(abi.encode(p));
    }

    function publicationHash(address core, P.Publication memory publication)
        internal
        view
        returns (bytes32)
    {
        Preimage memory p;
        p.domain = RECORD_DOMAIN;
        p.chainId = block.chainid;
        p.host = publication.metadataHost;
        p.core = core;
        p.recorder = publication.recorder;
        p.collectionId = publication.collectionId;
        p.recordType = publication.recordType;
        p.subjectId = publication.subjectId;
        p.contentHash = hashRef(
            publication.payloadAlgorithm,
            abi.encode(publication.payloadHash),
            publication.canonicalizationId
        );
        p.uriHash = publication.uriHash;
        p.schemaId = publication.schemaId;
        p.signatureHash = hashRef(0, bytes(""), 0);
        p.effectiveAt = publication.effectiveAt;
        return keccak256(abi.encode(p));
    }

    function nextChain(
        uint256 scopeKey,
        bytes32 recordType,
        bytes32 previous,
        bytes32 hash,
        uint64 index
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                CHAIN_DOMAIN,
                block.chainid,
                address(this),
                scopeKey,
                recordType,
                previous,
                hash,
                index
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationDefinitions.sol";
import "./StreamWorkRecordDefinitions.sol";
import "./StreamCollectionRecordHashes.sol";
import "./StreamRecordFamilies.sol";
import "./StreamRecordArtistIdentityReads.sol";
import "../../interfaces/stream/metadata/IStreamConservationRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../../interfaces/stream/metadata/IStreamCollectionRecordReceipts.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import "../../interfaces/stream/artist/IStreamArtistBindingOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistAttributionOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistRecordPublicationOwner.sol";
import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Fixed conservation dependency graph and complete registered interpretation bytes.
/// @dev Stateless bounded reads; constructor selection and current use are separate caller decisions.
library StreamConservationRecordContext {
    bytes32 private constant RAW_BYTES = keccak256("RAW_BYTES");
    bytes32 private constant READ_GAS = keccak256("6529STREAM_GGP_METADATA_DEPENDENCY_READ_GAS");

    struct Dependencies {
        // Core, metadata host, schema registry, byte store.
        address[4] targets;
        bytes32[4] codeHashes;
        // Facade, Coordinator, Identity, Binding, Attribution owners.
        address[5] artists;
        bytes32[5] artistCodeHashes;
        uint256 chainId;
        uint256 readGas;
    }

    function currentContext(Dependencies memory d) public view returns (Dependencies memory) {
        if (block.chainid != d.chainId) {
            revert IStreamConservationRecordSelection.ConservationDependencyChanged(d.targets[0]);
        }
        for (uint256 i; i < 4; ++i) {
            _code(d.targets[i], d.codeHashes[i]);
        }
        // The immutable pinned host's getter has no external calls.
        d.readGas = IStreamGasParameterHost(d.targets[1]).gasParameter(READ_GAS);
        if (d.readGas == 0 || d.readGas > type(uint64).max) {
            revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        }
        if (
            _word(
                        _fixed(
                            d,
                            d.targets[1],
                            abi.encodeCall(
                                IERC165.supportsInterface,
                                (type(IStreamCollectionRecordReceipts).interfaceId)
                            ),
                            32
                        ),
                        0
                    ) != bytes32(uint256(1))
                || _word(
                        _fixed(
                            d,
                            d.targets[2],
                            abi.encodeCall(
                                IERC165.supportsInterface,
                                (type(IStreamSchemaDocumentFacts).interfaceId)
                            ),
                            32
                        ),
                        0
                    ) != bytes32(uint256(1))
        ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        if (
            _hash(d, d.targets[1], "coreCodeHash()") != d.codeHashes[0]
                || _hash(d, d.targets[1], "schemaRegistryCodeHash()") != d.codeHashes[2]
                || _hash(d, d.targets[1], "chunkStoreCodeHash()") != d.codeHashes[3]
                || _address(d, d.targets[1], "core()") != d.targets[0]
                || _address(d, d.targets[1], "schemaRegistry()") != d.targets[2]
                || _address(d, d.targets[1], "chunkStore()") != d.targets[3]
                || _address(d, d.targets[2], "chunkStore()") != d.targets[3]
        ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        _selected(d, keccak256("COLLECTION_METADATA"), d.targets[1], d.codeHashes[1]);
        if (d.artists[0] != address(0)) {
            for (uint256 i; i < 5; ++i) {
                _code(d.artists[i], d.artistCodeHashes[i]);
            }
            bytes32 expectedArtists = keccak256(abi.encode(d.artists, d.artistCodeHashes));
            Dependencies memory fresh = pinArtists(d);
            if (keccak256(abi.encode(fresh.artists, fresh.artistCodeHashes)) != expectedArtists) {
                revert IStreamConservationRecordSelection.ConservationAssociationChanged();
            }
        }
        return d;
    }

    function pinArtists(Dependencies memory d) public view returns (Dependencies memory) {
        StreamRecordArtistIdentityReads.Pins memory known = StreamRecordArtistIdentityReads.resolve(
            d.targets[1], d.targets[0], d.chainId, d.readGas
        );
        for (uint256 i; i < 3; ++i) {
            d.artists[i] = known.targets[i];
            d.artistCodeHashes[i] = known.codeHashes[i];
        }
        bytes memory suite =
            _fixed(d, d.artists[1], abi.encodeWithSignature("suiteConfiguration()"), 544);
        for (uint256 i; i < 17; ++i) {
            if (i != 15 && uint256(_word(suite, i)) > type(uint160).max) {
                revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.artists[
                        1
                    ]);
            }
        }
        if (
            _word(suite, 0) != bytes32(uint256(uint160(d.artists[0])))
                || _word(suite, 9) != bytes32(uint256(uint160(d.targets[0])))
        ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        d.artists[3] = address(uint160(uint256(_word(suite, 2))));
        d.artists[4] = address(uint160(uint256(_word(suite, 6))));
        for (uint256 i = 3; i < 5; ++i) {
            if (d.artists[i].code.length == 0) {
                revert IStreamConservationRecordSelection.ConservationDependencyChanged(d.artists[
                        i
                    ]);
            }
            d.artistCodeHashes[i] = d.artists[i].codehash;
            if (
                _address(d, d.artists[i], "core()") != d.targets[0]
                    || _address(d, d.artists[i], "artistRegistry()") != d.artists[0]
                    || _address(d, d.artists[i], "operationCoordinator()") != d.artists[1]
                    || _hash(d, d.artists[i], "deploymentChainId()") != bytes32(d.chainId)
            ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        }
        _selected(d, keccak256("ARTIST_REGISTRY"), d.artists[0], d.artistCodeHashes[0]);
        return d;
    }

    function association(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId
    ) public view returns (IStreamConservationRecordSelection.Association memory a) {
        bytes memory raw = _fixed(
            d, d.artists[3], abi.encodeCall(IStreamArtistBindingOwner.binding, (collectionId)), 320
        );
        T.Binding memory b = abi.decode(raw, (T.Binding));
        _canonical(d.artists[3], raw, abi.encode(b));
        if (b.artistId == 0) {
            T.Binding memory empty;
            if (keccak256(raw) != keccak256(abi.encode(empty))) {
                revert IStreamConservationRecordSelection.ConservationAssociationChanged();
            }
            return a;
        }
        raw = _fixed(
            d,
            d.artists[4],
            abi.encodeCall(IStreamArtistAttributionOwner.attributionState, (collectionId)),
            64
        );
        (uint8 status, uint64 generation) = abi.decode(raw, (uint8, uint64));
        _canonical(d.artists[4], raw, abi.encode(status, generation));
        if (
            !b.accepted || (status != 2 && status != 3) || b.bindingHash == 0 || b.generation == 0
                || b.generation != generation || b.identityRecordHash == 0
                || b.artistAddress == address(0)
        ) revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        StreamRecordArtistIdentityReads.Pins memory pins;
        for (uint256 i; i < 3; ++i) {
            pins.targets[i] = d.artists[i];
            pins.codeHashes[i] = d.artistCodeHashes[i];
        }
        bytes32 identity = StreamRecordArtistIdentityReads.knownIdentity(
            d.targets[1], d.targets[0], d.chainId, pins, b.artistId, d.readGas
        );
        if (identity != b.identityRecordHash) {
            revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        }
        return IStreamConservationRecordSelection.Association(
            b.artistId, b.bindingHash, b.generation, identity
        );
    }

    /// @notice Fresh direct principal authorization only for the explicit one-way local lock.
    /// @dev Historical record materialization never calls this current-authority predicate.
    function requireLocker(
        Dependencies memory d,
        bytes32 artistId,
        bytes32 identityRecordHash,
        address caller
    ) public view {
        bytes memory raw = _fixed(
            d,
            d.artists[2],
            abi.encodeCall(IStreamArtistIdentityOwner.authorityState, (artistId)),
            128
        );
        (address authority, uint8 authorityClass, uint8 status, bytes32 identity) =
            abi.decode(raw, (address, uint8, uint8, bytes32));
        _canonical(d.artists[2], raw, abi.encode(authority, authorityClass, status, identity));
        if (
            authority == address(0) || authority != caller || authorityClass != 1 || status != 1
                || identity != identityRecordHash || identity == 0
        ) {
            revert IStreamConservationRecordSelection.ConservationSelectionAuthorityRequired();
        }
    }

    function definitions(Dependencies memory d) public view {
        definition(
            d,
            StreamConservationDefinitions.INTENT_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.INTENT_SCHEMA_HASH,
            StreamConservationDefinitions.INTENT_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.INTENT_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.INTENT_PROFILE_HASH,
            StreamConservationDefinitions.INTENT_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.WAIVER_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.WAIVER_SCHEMA_HASH,
            StreamConservationDefinitions.WAIVER_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.WAIVER_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.WAIVER_PROFILE_HASH,
            StreamConservationDefinitions.WAIVER_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        interviewDefinitions(d);
    }

    function interviewDefinitions(Dependencies memory d) public view {
        definition(
            d,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_HASH,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.INTERVIEW_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.INTERVIEW_PROFILE_HASH,
            StreamConservationDefinitions.INTERVIEW_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.CATALOG_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.CATALOG_SCHEMA_HASH,
            StreamConservationDefinitions.CATALOG_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.CATALOG_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.CATALOG_PROFILE_HASH,
            StreamConservationDefinitions.CATALOG_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamWorkRecordDefinitions.CANON_ID,
            IStreamSchemaRegistry.DocumentKind.CANONICALIZATION,
            StreamWorkRecordDefinitions.CANON_HASH,
            StreamWorkRecordDefinitions.CANON_BYTES,
            RAW_BYTES,
            true
        );
    }

    function document(Dependencies memory d, bytes32 id)
        public
        view
        returns (IStreamSchemaDocumentFacts.DocumentFacts memory row)
    {
        bytes memory raw = _fixed(
            d, d.targets[2], abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)), 288
        );
        row = abi.decode(raw, (IStreamSchemaDocumentFacts.DocumentFacts));
        _canonical(d.targets[2], raw, abi.encode(row));
    }

    function definition(
        Dependencies memory d,
        bytes32 id,
        IStreamSchemaRegistry.DocumentKind kind,
        bytes32 hash,
        uint256 length,
        bytes32 canon,
        bool firstVersion
    ) public view returns (bytes memory payload) {
        IStreamSchemaDocumentFacts.DocumentFacts memory row = document(d, id);
        // The pinned Registry derives each immutable ID from its exact registered name.
        // URI is registration metadata; do not claim to re-create its declaration preimage.
        if (
            !row.exists || row.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || row.kind != kind || row.canonicalizationId != canon
                || (firstVersion && row.supersedesId != 0) || row.totalBytes != length
                || row.contentHash != hash || row.declarationHash == 0 || row.chunkCount == 0
                || row.chunkCount > 64 || length > 524288
        ) revert IStreamConservationRecordSelection.ConservationDefinitionUnavailable(id);
        for (uint256 i; i < row.chunkCount; ++i) {
            bytes32 chunkHash = _word(
                _fixed(
                    d,
                    d.targets[2],
                    abi.encodeCall(IStreamSchemaDocumentFacts.documentChunkHashAt, (id, i)),
                    32
                ),
                0
            );
            bytes memory chunk = _chunk(d, chunkHash);
            if (
                chunk.length == 0 || chunk.length > 8192
                    || (i + 1 < row.chunkCount && chunk.length != 8192)
                    || payload.length + chunk.length > length
            ) revert IStreamConservationRecordSelection.ConservationDefinitionUnavailable(id);
            payload = bytes.concat(payload, chunk);
        }
        if (payload.length != length || keccak256(payload) != hash) {
            revert IStreamConservationRecordSelection.ConservationDefinitionUnavailable(id);
        }
    }

    function _selected(Dependencies memory d, bytes32 kind, address target, bytes32 codeHash)
        private
        view
    {
        bytes memory raw = _fixed(
            d, d.targets[0], abi.encodeWithSignature("getSatellitePointer(bytes32)", kind), 320
        );
        if (
            uint256(_word(raw, 0)) > type(uint160).max || uint256(_word(raw, 2)) > 1
                || uint256(_word(raw, 4)) & type(uint224).max != 0
                || uint256(_word(raw, 5)) > type(uint160).max
                || uint256(_word(raw, 6)) > type(uint8).max
                || uint256(_word(raw, 9)) > type(uint64).max
        ) revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.targets[0]);
        if (
            _word(raw, 0) != bytes32(uint256(uint160(target))) || _word(raw, 1) != codeHash
                || _word(raw, 3) != kind || _word(raw, 6) != bytes32(uint256(1))
        ) revert IStreamConservationRecordSelection.ConservationHostNotSelected();
    }

    function _code(address target, bytes32 hash) private view {
        if (target.code.length == 0 || target.codehash != hash) {
            revert IStreamConservationRecordSelection.ConservationDependencyChanged(target);
        }
    }

    function _address(Dependencies memory d, address target, string memory signature)
        private
        view
        returns (address)
    {
        uint256 word = uint256(_hash(d, target, signature));
        if (word > type(uint160).max) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        return address(uint160(word));
    }

    function _hash(Dependencies memory d, address target, string memory signature)
        private
        view
        returns (bytes32)
    {
        return _word(_fixed(d, target, abi.encodeWithSignature(signature), 32), 0);
    }

    function _chunk(Dependencies memory d, bytes32 hash) private view returns (bytes memory chunk) {
        bytes memory raw = _read(
            d, d.targets[3], abi.encodeCall(StreamSchemaDocumentStore.readChunk, (hash)), 8256
        );
        chunk = abi.decode(raw, (bytes));
        _canonical(d.targets[3], raw, abi.encode(chunk));
        if (keccak256(chunk) != hash) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.targets[3]);
        }
    }

    function _word(bytes memory raw, uint256 index) private pure returns (bytes32 word) {
        assembly ("memory-safe") { word := mload(add(add(raw, 32), mul(index, 32))) }
    }

    function _canonical(address target, bytes memory raw, bytes memory encoded) private pure {
        if (raw.length != encoded.length || keccak256(raw) != keccak256(encoded)) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
    }

    function _fixed(Dependencies memory d, address target, bytes memory input, uint256 size)
        private
        view
        returns (bytes memory raw)
    {
        raw = _read(d, target, input, size);
        if (raw.length != size) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
    }

    function _read(Dependencies memory d, address target, bytes memory input, uint256 maximum)
        private
        view
        returns (bytes memory raw)
    {
        uint256 cap = d.readGas;
        raw = new bytes(maximum);
        if (cap == 0 || cap > type(uint64).max || gasleft() <= cap + cap / 63 + 10000) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(raw, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        assembly ("memory-safe") { mstore(raw, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamRecordJson.sol";
import "./StreamConservationDefinitions.sol";
import "../../interfaces/stream/metadata/StreamConservationRecordTypes.sol";

/// @notice Closed conservation fields; references are commitments, never verified external facts.
library StreamConservationRecordFields {
    error InvalidConservationWitness();

    function referenceJSON(StreamConservationRecordTypes.Reference memory r)
        public
        pure
        returns (string memory)
    {
        if (r.canonicalizationId == 0 || r.algorithm == 0 || r.algorithm > 6) {
            revert InvalidConservationWitness();
        }
        if (r.algorithm == 4 || r.algorithm == 5) {
            if (r.digest.length == 0 || r.digest.length > 128) revert InvalidConservationWitness();
        } else if (r.digest.length != 32) {
            revert InvalidConservationWitness();
        }
        StreamMetadataRenderer.requireValidUtf8ContentUri(
            "CONSERVATION_REFERENCE", r.uri, 2048, false
        );
        return string.concat(
            '{"hash":{"algorithm":',
            string(abi.encodePacked(bytes1(uint8(48 + r.algorithm)))),
            ',"canonicalizationId":',
            StreamRecordJson.hexValue(r.canonicalizationId),
            ',"digest":',
            _hexBytes(r.digest),
            '},"uri":',
            StreamRecordJson.quote(r.uri, 2048, false),
            "}"
        );
    }

    function requireEmptyReference(StreamConservationRecordTypes.Reference memory r) public pure {
        if (
            r.algorithm != 0 || r.canonicalizationId != 0 || r.digest.length != 0
                || bytes(r.uri).length != 0
        ) {
            revert InvalidConservationWitness();
        }
    }

    function requireHeader(bytes32 subjectId, bytes32 profileHash, bytes32 expectedProfile)
        public
        pure
    {
        if (subjectId == 0 || profileHash != expectedProfile) {
            revert InvalidConservationWitness();
        }
    }

    function artistJSON(StreamConservationRecordTypes.ArtistClaim memory a)
        public
        pure
        returns (string memory)
    {
        if (a.artistId == 0 || a.bindingGeneration == 0 || a.bindingHash == 0) {
            revert InvalidConservationWitness();
        }
        return string.concat(
            '{"artistId":',
            StreamRecordJson.hexValue(a.artistId),
            ',"bindingGeneration":',
            StreamRecordJson.unsigned(a.bindingGeneration),
            ',"bindingHash":',
            StreamRecordJson.hexValue(a.bindingHash),
            ',"statementOrigin":',
            a.origin == StreamConservationRecordTypes.StatementOrigin.ARTIST_INTENT
                ? '"artist_intent"'
                : '"estate_statement"',
            "}"
        );
    }

    function interviewJSON(StreamConservationRecordTypes.InterviewEntry memory e)
        public
        pure
        returns (string memory)
    {
        StreamConservationRecordTypes.InterviewRecord memory r = e.record;
        if (e.status == StreamConservationRecordTypes.InterviewStatus.PRESENT) {
            requireEmptyReference(e.waiverStatement);
            if (
                r.chainId == 0 || r.core == address(0) || r.host == address(0) || r.recordHash == 0
                    || r.schemaId != StreamConservationDefinitions.INTERVIEW_SCHEMA_ID
                    || r.profileHash != StreamConservationDefinitions.INTERVIEW_PROFILE_HASH
            ) revert InvalidConservationWitness();
            string memory locator = string.concat(
                '{"chainId":',
                StreamRecordJson.unsigned(r.chainId),
                ',"core":',
                StreamRecordJson.account(r.core),
                ',"host":',
                StreamRecordJson.account(r.host),
                ',"profileHash":',
                StreamRecordJson.hexValue(r.profileHash),
                ',"recordHash":',
                StreamRecordJson.hexValue(r.recordHash),
                ',"schemaId":',
                StreamRecordJson.hexValue(r.schemaId),
                "}"
            );
            return string.concat(
                '{"kind":"present","payload":', referenceJSON(r.payload), ',"record":', locator, "}"
            );
        }
        if (
            r.chainId != 0 || r.core != address(0) || r.host != address(0) || r.recordHash != 0
                || r.schemaId != 0 || r.profileHash != 0
        ) revert InvalidConservationWitness();
        requireEmptyReference(r.payload);
        return string.concat(
            '{"kind":"interview_waived","statement":', referenceJSON(e.waiverStatement), "}"
        );
    }

    /// @notice Preserve every row and its order with one bounded output allocation.
    function arrayJSON(bytes[] memory rows) public pure returns (string memory) {
        uint256 size = 2;
        for (uint256 i; i < rows.length; ++i) {
            size += rows[i].length + (i == 0 ? 0 : 1);
            if (size > 8192) revert InvalidConservationWitness();
        }
        bytes memory out = new bytes(size);
        out[0] = "[";
        uint256 offset = 1;
        for (uint256 i; i < rows.length; ++i) {
            if (i != 0) out[offset++] = ",";
            _copyRow(rows[i], out, offset);
            offset += rows[i].length;
        }
        out[offset] = "]";
        return string(out);
    }

    function requirePayloadSize(bytes memory value) public pure returns (bytes memory) {
        if (value.length == 0 || value.length > 8192) revert InvalidConservationWitness();
        return value;
    }

    function _hexBytes(bytes memory input) private pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory out = new bytes(4 + input.length * 2);
        out[0] = '"';
        out[1] = "0";
        out[2] = "x";
        out[out.length - 1] = '"';
        for (uint256 i; i < input.length; ++i) {
            out[3 + i * 2] = alphabet[uint8(input[i]) >> 4];
            out[4 + i * 2] = alphabet[uint8(input[i]) & 15];
        }
        return string(out);
    }

    function _copyRow(bytes memory row, bytes memory out, uint256 offset) private pure {
        assembly ("memory-safe") {
            let size := mload(row)
            let source := add(row, 32)
            let target := add(add(out, 32), offset)
            let cursor := 0
            for { } iszero(gt(add(cursor, 32), size)) { cursor := add(cursor, 32) } {
                mstore(add(target, cursor), mload(add(source, cursor)))
            }
            if lt(cursor, size) {
                let tail := mload(add(source, cursor))
                let index := 0
                for { } lt(cursor, size) {
                    cursor := add(cursor, 1)
                    index := add(index, 1)
                } { mstore8(add(target, cursor), byte(index, tail)) }
            }
        }
    }
}

