        returns (E.Receipt memory, bytes memory identifier, bytes memory signature);
    function fixityDigest(E.Fixity calldata fixity) external view returns (bytes32);
    function recordFixity(E.Fixity calldata fixity, bytes calldata signature)
        external
        returns (bytes32);
    function fixity(bytes32 hash) external view returns (E.Fixity memory, bytes memory signature);
    function latestFixity(bytes32 receiptHash) external view returns (bytes32);
    function recordCoverage(bytes32 firstReceipt, bytes32 secondReceipt) external returns (bytes32);
    function coverage(bytes32 hash) external view returns (E.Coverage memory);
    function requireCoverage(bytes32 hash, bytes32 artistId, bytes32 objectHash)
        external
        view
        returns (E.Coverage memory);
    function nonceUsed(bytes32 key) external view returns (bool);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../../vendor/openzeppelin/IERC165.sol";

/// @notice Interface for outside-Core collection preservation and provenance records.
interface IStreamPreservationRecords is IERC165 {
    /// @notice Tagged hash reference for PREMIS, C2PA, IIIF, fixity, and archive payloads.
    /// @dev Variable-length hash algorithms are opaque byte commitments at launch.
    /// `canonicalizationId` is presence-validated; the release manifest defines recognized
    /// canonicalization profile IDs for offchain consumers.
    struct HashRef {
        uint16 algorithm;
        bytes digest;
        bytes32 canonicalizationId;
    }

    /// @notice Generic launch record for preservation, provenance, relationship, and fixity data.
    struct CollectionRecord {
        bytes32 recordType;
        bytes32 subjectId;
        HashRef contentHash;
        string uri;
        bytes32 schemaId;
        bytes32 signatureScheme;
        HashRef signatureHash;
        uint64 effectiveAt;
    }

    /// @notice Stored summary for cheap latest-record reads and event-log verification.
    struct CollectionRecordSummary {
        uint256 collectionId;
        bytes32 recordType;
        bytes32 subjectId;
        bytes32 recordHash;
        uint16 contentHashAlgorithm;
        bytes32 contentHashDigestHash;
        bytes32 contentHashCanonicalizationId;
        string uri;
        bytes32 uriHash;
        bytes32 schemaId;
        bytes32 signatureScheme;
        uint16 signatureHashAlgorithm;
        bytes32 signatureHashDigestHash;
        bytes32 signatureHashCanonicalizationId;
        uint64 effectiveAt;
        address recorder;
        uint64 recordedAt;
        uint8 authorizationClass;
    }

    /// @notice Reverts when Core is not a deployed 6529Stream Core.
    error InvalidCoreContract();
    /// @notice Reverts when the admin dependency is not a StreamAdmins contract.
    error InvalidAdminContract();
    /// @notice Reverts when the family classifier is not the required deployed registry.
    error InvalidRecordFamilyRegistry();
    /// @notice Reverts when caller lacks global or target-scoped function authority.
    error FunctionAdminUnauthorized(address caller, bytes4 selector);
    /// @notice Reverts when preservation mutation pause is active.
    error MetadataMutationPaused();
    /// @notice Reverts when the collection has not been created in Core.
    error CollectionDoesNotExist(uint256 collectionId);
    /// @notice Reverts when required record identity fields are zero.
    error InvalidCollectionRecord(bytes32 recordType, bytes32 subjectId, bytes32 schemaId);
    /// @notice Reverts when a hash reference is malformed or uses an unsupported algorithm.
    error InvalidHashRef(uint16 algorithm, uint256 digestLength);
    /// @notice Reverts when a preservation URI exceeds launch limits.
    error PreservationURITooLarge(uint256 actual, uint256 maximum);
    /// @notice Reverts when the same record hash has already been stored.
    error CollectionRecordAlreadyExists(bytes32 recordHash);
    /// @notice Reverts when an explicit recorder identity is zero.
    error InvalidCollectionRecordRecorder(address recorder);

    /// @notice Emitted when the admin dependency changes.
    event PreservationAdminContractUpdated(
        address indexed oldAdminContract, address indexed newAdminContract, address indexed admin
    );
    /// @notice Emitted when a generic collection preservation record is stored.
    event CollectionRecordRecorded(
        uint256 indexed collectionId,
        bytes32 indexed recordType,
        bytes32 indexed subjectId,
        CollectionRecord record,
        bytes32 recordHash,
        address recorder,
        uint8 authorizationClass
    );

    /// @notice Returns the Core contract this preservation module extends.
    function streamCore() external view returns (address);
    /// @notice Returns the active StreamAdmins dependency.
    function adminsContract() external view returns (address);
    /// @notice Returns the immutable exact record-family classifier/authority host.
    function recordFamilyRegistry() external view returns (address);
    /// @notice Returns true for deployment validation.
    function isStreamPreservationRecords() external pure returns (bool);
    /// @notice Returns the module family beacon.
    function streamModuleFamily() external pure returns (bytes32);
    /// @notice Returns the module version beacon.
    function streamModuleVersion() external pure returns (bytes32);
    /// @notice Returns the launch schema hash for this module.
    function streamModuleSchemaHash() external view returns (bytes32);
    /// @notice Returns the immediate predecessor module, or zero for the first version.
    function streamModuleSupersedes() external view returns (address);
    /// @notice Updates the active admin contract.
    function updateAdminContract(address newAdminsContract) external;
    /// @notice Stores a generic preservation record and updates the latest subject pointer.
    /// @dev Intentionally omits Core freeze checks so append-only preservation records can
    /// document frozen collections. Re-recording the exact same collection payload reverts
    /// because the derived record hash is already present.
    function recordCollectionRecord(uint256 collectionId, CollectionRecord calldata record)
        external
        returns (bytes32 recordHash);
    /// @notice Returns the caller's latest recorded hash for one collection/type/subject key.
    /// @dev Latest is last-write-wins by record time within the caller's recorder scope, not max
    /// `effectiveAt`.
    function latestCollectionRecordHash(uint256 collectionId, bytes32 recordType, bytes32 subjectId)
        external
        view
        returns (bytes32);
    /// @notice Returns one recorder's latest hash for a collection/type/subject key.
    function latestCollectionRecordHashFor(
        uint256 collectionId,
        bytes32 recordType,
        bytes32 subjectId,
        address recorder
    ) external view returns (bytes32);
    /// @notice Returns the stored summary for a record hash.
    function collectionRecordSummary(bytes32 recordHash)
        external
        view
        returns (CollectionRecordSummary memory);
    /// @notice Returns the full stored payload for a record hash.
    /// @dev Signature fields are hash commitments only; this contract does not verify signatures.
    function collectionRecord(bytes32 recordHash) external view returns (CollectionRecord memory);
    /// @notice Computes the caller-scoped domain-separated record hash without writing.
    function deriveCollectionRecordHash(uint256 collectionId, CollectionRecord calldata record)
        external
        view
        returns (bytes32);
    /// @notice Computes the domain-separated record hash for an explicit recorder without writing.
    function deriveCollectionRecordHashFor(
        address recorder,
        uint256 collectionId,
        CollectionRecord calldata record
    ) external view returns (bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamArchivalTypes as A } from "./StreamArchivalTypes.sol";

/// @notice Full external-object commitments and attributed preservation evidence.
/// @dev Flat hashes are full-retrieval fixity observations; native inclusion proves its
///      separately identified Arweave data root, under the named quorum checkpoint model.
library StreamExternalArtifactTypes {
    struct ObjectIdentity {
        bytes32 artistId;
        bytes32 schemaId;
        bytes32 canonicalizationId;
        bytes32 contentHash;
        bytes32 sha256Digest;
        bytes32 arweaveDataRoot;
        uint64 byteSize;
        bytes32 formatId;
        bytes32 formatCatalogId;
        bytes32 formatCatalogHash;
    }

    struct NativeFacts {
        bytes32 recordHash;
        bytes32 networkId;
        bytes32 transactionId;
        bytes32 dataRoot;
        uint64 dataSize;
        bytes32 configurationHash;
        bytes32 firstChunkDigest;
        bytes32 lastChunkDigest;
    }

    struct NativeRecord {
        bytes32 recordHash;
        A.Checkpoint checkpoint;
        bytes32 firstChunkDigest;
        bytes32 lastChunkDigest;
        bytes transactionPath;
        bytes firstDataPath;
        bytes lastDataPath;
        A.ObserverProof[] certificate;
        uint64 recordedAt;
    }

    struct Receipt {
        bytes32 objectHash;
        bytes32 familyRecordHash;
        bytes32 storageIdentifierHash;
        bytes32 evidenceClass;
        bytes32 proofProfileHash;
        bytes32 proofRecordHash;
        address writer;
        uint64 observedAt;
        uint256 nonce;
        uint64 deadline;
    }

    /// @dev Every expected/observed commitment is signed, including on failure.
    struct Fixity {
        bytes32 receiptHash;
        bytes32 objectHash;
        bytes32 familyRecordHash;
        bytes32 storageIdentifierHash;
        bytes32 profileHash;
        bytes32 expectedSha256;
        bytes32 observedSha256;
        bytes32 expectedKeccak256;
        bytes32 observedKeccak256;
        bytes32 expectedArweaveRoot;
        bytes32 observedArweaveRoot;
        uint64 expectedSize;
        uint64 observedSize;
        uint64 checkedAt;
        uint8 outcome;
        bytes32 reportHash;
        bytes32 previousFixityHash;
        bytes32 repairReportHash;
        address verifier;
        uint256 nonce;
        uint64 deadline;
    }

    /// @notice Unsaved present liveness for two exact original receipts; never a recorded coverage.
    /// @dev Later passing fixity may change these two fixity hashes without changing the originals.
    struct CurrentPair {
        bytes32 objectHash;
        bytes32 artistId;
        bytes32 contentHash;
        bytes32 sha256Digest;
        bytes32 arweaveDataRoot;
        uint64 byteSize;
        bytes32 firstFamilyRecordHash;
        bytes32 secondFamilyRecordHash;
        bytes32 firstReceiptHash;
        bytes32 secondReceiptHash;
        bytes32 firstFixityHash;
        bytes32 secondFixityHash;
        bytes32 checkpointHash;
        bytes32 profileHash;
    }

    struct Coverage {
        bytes32 coverageHash;
        bytes32 objectHash;
        bytes32 artistId;
        bytes32 contentHash;
        bytes32 sha256Digest;
        bytes32 arweaveDataRoot;
        uint64 byteSize;
        bytes32 firstFamilyRecordHash;
        bytes32 secondFamilyRecordHash;
        bytes32 firstReceiptHash;
        bytes32 secondReceiptHash;
        bytes32 firstFixityHash;
        bytes32 secondFixityHash;
        bytes32 checkpointHash;
        bytes32 profileHash;
    }
}

